1: import assert from 'node:assert/strict';
2: import { before, after } from './functions.mjs';
3: 
4: async function scenario(fn, outcomes, retries, sleepRejects = false) {
5:   const trace = { calls: 0, effects: 0, delays: [], result: null, error: null };
6:   try {
7:     trace.result = await fn(async () => {
8:       const outcome = outcomes[trace.calls++];
9:       assert.ok(outcome, 'the supplied retry budget must bound send calls');
10:       if (outcome.effect) trace.effects++;
11:       if (outcome.error) throw outcome.error;
12:       return 'delivered';
13:     }, async (delay) => {
14:       trace.delays.push(delay);
15:       if (sleepRejects) throw { label: 'sleep-failed' };
16:     }, retries);
17:   } catch (error) {
18:     trace.error = error.label;
19:   }
20:   return trace;
21: }
22: const transient = { label: 'transient', retryable: true };
23: const permanent = { label: 'permanent', retryable: false };
24: const results = {};
25: for (const [name, fn] of Object.entries({ before, after })) {
26:   results[name] = {
27:     permanent: await scenario(fn, [{ error: permanent }, {}], 2),
28:     exhausted: await scenario(fn, Array(3).fill({ error: transient }), 2),
29:     zeroBudget: await scenario(fn, [{ error: transient }], 0),
30:     duplicate: await scenario(fn, [{ effect: true, error: transient }, { effect: true }], 2),
31:     sleepFailure: await scenario(fn, [{ error: transient }], 2, true),
32:     concurrentCalls: await Promise.all([1, 2].map(() => scenario(fn, [{ effect: true }], 2))),
33:   };
34: }
35: assert.equal(results.before.permanent.calls, 2);
36: assert.equal(results.after.permanent.calls, 1);
37: assert.equal(results.after.permanent.error, 'permanent');
38: assert.deepEqual(results.before.exhausted.delays, [10, 10]);
39: assert.deepEqual(results.after.exhausted.delays, [10, 20]);
40: for (const result of Object.values(results)) {
41:   assert.equal(result.exhausted.calls, 3, 'retries counts extra attempts, not all attempts');
42:   assert.equal(result.exhausted.error, 'transient');
43:   assert.equal(result.zeroBudget.calls, 1);
44:   assert.deepEqual(result.zeroBudget.delays, []);
45:   assert.equal(result.duplicate.effects, 2, 'a lost acknowledgment permits duplicate side effects');
46:   assert.equal(result.sleepFailure.calls, 1, 'a rejected sleep prevents another send');
47:   assert.equal(result.sleepFailure.error, 'sleep-failed');
48:   assert.equal(result.concurrentCalls.reduce((sum, item) => sum + item.effects, 0), 2);
49: }
50: console.log(JSON.stringify({ assumptions: 'Deterministic modeled send outcomes and immediate sleep promises; no timing or production measurement.', results }, null, 2));

